corrected_code:
const resolvers = {
  Mutation: {
    cancelOrder: async (parent, args, context) => {
      const order = await Order.findByPk(args.orderId);
      if (order.customerId !== context.user.id) throw new Error('Not authorized');
      order.status = 'cancelled';
      await order.save();
      return order;
    }
  }
};
